START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261015150109_AddSupplierStockSync') THEN
    CREATE TABLE "Suppliers" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Code" text NOT NULL,
        "Name" text NOT NULL,
        "FeedFormat" text NOT NULL,
        "IsEnabled" boolean NOT NULL,
        "MinExpectedItems" integer NOT NULL,
        "StaleAfterHours" integer NOT NULL,
        CONSTRAINT "PK_Suppliers" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261015150109_AddSupplierStockSync') THEN
    CREATE TABLE "ProductSupplierLinks" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "ProductId" integer NOT NULL,
        "SupplierId" integer NOT NULL,
        "SupplierSku" text NOT NULL,
        "LastQuantity" integer,
        "LastSeenAt" timestamp with time zone,
        "CreatedAt" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_ProductSupplierLinks" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ProductSupplierLinks_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_ProductSupplierLinks_Suppliers_SupplierId" FOREIGN KEY ("SupplierId") REFERENCES "Suppliers" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261015150109_AddSupplierStockSync') THEN
    CREATE TABLE "StockSyncRuns" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "SupplierId" integer NOT NULL,
        "StartedAt" timestamp with time zone NOT NULL,
        "FinishedAt" timestamp with time zone NOT NULL,
        "Succeeded" boolean NOT NULL,
        "FeedItemCount" integer NOT NULL,
        "MatchedCount" integer NOT NULL,
        "MissingCount" integer NOT NULL,
        "Error" text,
        CONSTRAINT "PK_StockSyncRuns" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_StockSyncRuns_Suppliers_SupplierId" FOREIGN KEY ("SupplierId") REFERENCES "Suppliers" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261015150109_AddSupplierStockSync') THEN
    INSERT INTO "Suppliers" ("Id", "Code", "FeedFormat", "IsEnabled", "MinExpectedItems", "Name", "StaleAfterHours")
    VALUES (1, 'pilmagazasi', 'akakce-xml', TRUE, 300, 'Pil Mağazası', 48);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261015150109_AddSupplierStockSync') THEN
    CREATE UNIQUE INDEX "IX_ProductSupplierLinks_ProductId_SupplierId" ON "ProductSupplierLinks" ("ProductId", "SupplierId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261015150109_AddSupplierStockSync') THEN
    CREATE UNIQUE INDEX "IX_ProductSupplierLinks_SupplierId_SupplierSku" ON "ProductSupplierLinks" ("SupplierId", "SupplierSku");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261015150109_AddSupplierStockSync') THEN
    CREATE INDEX "IX_StockSyncRuns_SupplierId_StartedAt" ON "StockSyncRuns" ("SupplierId", "StartedAt");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261015150109_AddSupplierStockSync') THEN
    CREATE UNIQUE INDEX "IX_Suppliers_Code" ON "Suppliers" ("Code");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261015150109_AddSupplierStockSync') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Suppliers"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Suppliers") + 1,
            nextval(pg_get_serial_sequence('"Suppliers"', 'Id'))),
        false);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261015150109_AddSupplierStockSync') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261015150109_AddSupplierStockSync', '9.0.8');
    END IF;
END $EF$;
COMMIT;

